(function(){AppModule.register({routes:[
{path:"models/providers",title:"个人模型与供应商",permission:"models.own",render(){const rows=DB.providers.filter(p=>p.ownerId==="u1").map(p=>'<tr><td><b>'+p.name+'</b><div class="small muted">'+p.kind+'</div></td><td>'+p.models+'</td><td>'+p.masked+'</td><td>'+UI.tag(p.status)+'</td><td>'+p.updated+'</td><td><button class="btn" data-action="verify-provider">测试连接</button></td></tr>').join("");return UI.head("个人模型与供应商","每位员工独立维护自己的供应商账号、API Key、模型能力和路由。",UI.btn("＋ 添加供应商","new-provider","primary"))+UI.card("我的资源配置",UI.table(["供应商","能力","凭据（脱敏）","状态","更新时间","操作"],rows))+'<div class="notice warn" style="margin-top:15px">个人 API Key 归员工本人配置。企业管理员不可查看明文，项目授权不会共享密钥，项目移交后接手员工需使用自己的配置。</div>';}},
{path:"models/usage",title:"个人调用记录",permission:"models.own",render(){return UI.head("个人调用记录","按任务追踪模型配置、供应商回执、用量和费用归属。",UI.btn("导出记录","export"))+UI.card("调用明细",UI.table(["调用","任务","能力 / 模型","执行人","配置人","用量","费用状态"],'<tr><td>INV-8812</td><td>T-8812</td><td>视频生成 / Model A</td><td>林知远</td><td>林知远</td><td>6 秒</td><td>'+UI.tag("待账单核实")+'</td></tr><tr><td>INV-8809</td><td>T-8803</td><td>视频生成 / Model A</td><td>林知远</td><td>林知远</td><td>失败调用</td><td>'+UI.tag("已记录")+'</td></tr>'))+'<div class="notice" style="margin-top:14px">费用承担方可能是员工个人账户、企业承担、报销或赠送额度。未取得可靠账单时不得显示为已确认实际成本。</div>';}}
]});})();